import type * as React from "react";
import { NavigationMenu as NavigationMenuPrimitive } from "@base-ui/react/navigation-menu";
import type { AnyRouter, RegisteredRouter } from "@tanstack/react-router";
import { cva } from "class-variance-authority";
import { cn } from "@/registry/erbium/lib/erbium-utils";
import { hasLinkTarget, linkFromTarget } from "@/registry/erbium/ui/link";
import type { AnyLinkTargetProps, HrefTargetProps, LinkTargetProps, NoTargetProps } from "@/registry/erbium/ui/link";
import { RotatingChevron } from "@/registry/erbium/ui/stateful-icon";

const NavigationMenuPositioner = ({
  className,
  side = "bottom",
  sideOffset = 8,
  align = "start",
  alignOffset = 0,
  ...props
}: NavigationMenuPrimitive.Positioner.Props) => (
  <NavigationMenuPrimitive.Portal>
    <NavigationMenuPrimitive.Positioner
      side={side}
      sideOffset={sideOffset}
      align={align}
      alignOffset={alignOffset}
      className={cn(
        "isolate z-50 h-(--positioner-height) w-(--positioner-width) max-w-(--available-width) transition-[top,left,right,bottom] duration-[0.35s] ease-[cubic-bezier(0.22,1,0.36,1)] data-instant:transition-none data-[side=bottom]:before:inset-s-0 data-[side=bottom]:before:inset-e-0 data-[side=bottom]:before:-top-2.5",
        className,
      )}
      {...props}
    >
      <NavigationMenuPrimitive.Popup className="relative h-(--popup-height) w-(--popup-width) origin-(--transform-origin) rounded-lg surface-overlay text-popover-foreground transition-[opacity,transform,width,height,scale,translate] duration-[0.35s] ease-[cubic-bezier(0.22,1,0.36,1)] outline-none data-ending-style:scale-90 data-ending-style:opacity-0 data-ending-style:duration-150 data-starting-style:scale-90 data-starting-style:opacity-0">
        <NavigationMenuPrimitive.Viewport className="relative size-full overflow-hidden" />
      </NavigationMenuPrimitive.Popup>
    </NavigationMenuPrimitive.Positioner>
  </NavigationMenuPrimitive.Portal>
);

const NavigationMenu = ({
  align = "start",
  className,
  children,
  ...props
}: NavigationMenuPrimitive.Root.Props &
  Pick<NavigationMenuPrimitive.Positioner.Props, "align">) => (
  <NavigationMenuPrimitive.Root
    data-slot="navigation-menu"
    className={cn(
      "group/navigation-menu relative flex max-w-max flex-1 items-center justify-center",
      className,
    )}
    {...props}
  >
    {children}
    <NavigationMenuPositioner align={align} />
  </NavigationMenuPrimitive.Root>
);

const NavigationMenuList = ({
  className,
  ...props
}: React.ComponentPropsWithRef<typeof NavigationMenuPrimitive.List>) => (
  <NavigationMenuPrimitive.List
    data-slot="navigation-menu-list"
    className={cn("group flex flex-1 list-none items-center justify-center gap-0", className)}
    {...props}
  />
);

const NavigationMenuItem = ({
  className,
  ...props
}: React.ComponentPropsWithRef<typeof NavigationMenuPrimitive.Item>) => (
  <NavigationMenuPrimitive.Item
    data-slot="navigation-menu-item"
    className={cn("relative", className)}
    {...props}
  />
);

const navigationMenuTriggerStyle = cva(
  "group/navigation-menu-trigger touch-target inline-flex control-size w-max items-center justify-center rounded-lg text-control-sm transition-all outline-none hover:bg-muted focus:bg-muted focus-visible:outline-1 disabled:pointer-events-none disabled:opacity-50 data-popup-open:bg-muted-selected data-popup-open:hover:bg-muted data-open:bg-muted-selected data-open:hover:bg-muted data-open:focus:bg-muted data-disabled:pointer-events-none data-disabled:opacity-50",
);

const NavigationMenuTrigger = ({
  className,
  children,
  ...props
}: NavigationMenuPrimitive.Trigger.Props) => (
  <NavigationMenuPrimitive.Trigger
    data-slot="navigation-menu-trigger"
    className={cn(navigationMenuTriggerStyle(), "group", className)}
    {...props}
  >
    {children} <RotatingChevron className="relative top-px ms-1 size-3" />
  </NavigationMenuPrimitive.Trigger>
);

const NavigationMenuContent = ({ className, ...props }: NavigationMenuPrimitive.Content.Props) => (
  <NavigationMenuPrimitive.Content
    data-slot="navigation-menu-content"
    className={cn(
      "h-full w-auto p-1 transition-[opacity,transform,translate] duration-[0.35s] ease-[cubic-bezier(0.22,1,0.36,1)] group-data-[viewport=false]/navigation-menu:rounded-lg group-data-[viewport=false]/navigation-menu:border group-data-[viewport=false]/navigation-menu:surface-overlay group-data-[viewport=false]/navigation-menu:text-popover-foreground group-data-[viewport=false]/navigation-menu:duration-300 data-ending-style:opacity-0 data-starting-style:opacity-0 data-ending-style:data-[activation-direction=left]:translate-x-[50%] data-starting-style:data-[activation-direction=left]:translate-x-[-50%] data-ending-style:data-[activation-direction=right]:translate-x-[-50%] data-starting-style:data-[activation-direction=right]:translate-x-[50%] data-[motion=from-end]:slide-in-from-right-52 data-[motion=from-start]:slide-in-from-left-52 data-[motion=to-end]:slide-out-to-right-52 data-[motion=to-start]:slide-out-to-left-52 data-[motion^=from-]:animate-in data-[motion^=from-]:fade-in data-[motion^=to-]:animate-out data-[motion^=to-]:fade-out **:data-[slot=navigation-menu-link]:focus:ring-0 **:data-[slot=navigation-menu-link]:focus:outline-none rtl:data-ending-style:data-[activation-direction=left]:-translate-x-[50%] rtl:data-starting-style:data-[activation-direction=left]:-translate-x-[-50%] rtl:data-ending-style:data-[activation-direction=right]:-translate-x-[-50%] rtl:data-starting-style:data-[activation-direction=right]:-translate-x-[50%] group-data-[viewport=false]/navigation-menu:data-open:animate-in group-data-[viewport=false]/navigation-menu:data-open:fade-in-0 group-data-[viewport=false]/navigation-menu:data-open:zoom-in-95 group-data-[viewport=false]/navigation-menu:data-closed:animate-out group-data-[viewport=false]/navigation-menu:data-closed:fade-out-0 group-data-[viewport=false]/navigation-menu:data-closed:zoom-out-95",
      className,
    )}
    {...props}
  />
);

type NavigationMenuLinkOwnProps = Pick<
  NavigationMenuPrimitive.Link.Props,
  "active" | "closeOnClick"
>;

type NavigationMenuLinkProps =
  | (NavigationMenuPrimitive.Link.Props & NoTargetProps)
  | (HrefTargetProps & NavigationMenuLinkOwnProps);

/**
 * A menu link. It takes Router's link options: `to` names a route, which preloads ahead of the
 * click and is marked current by Router; `href` names a fully built or external URL.
 */
function NavigationMenuLink(props: NavigationMenuLinkProps): React.ReactElement;

// Restores Router's generics, so `to` and `params` type against the app's routes.
function NavigationMenuLink<
  TRouter extends AnyRouter = RegisteredRouter,
  const TFrom extends string = string,
  const TTo extends string | undefined = undefined,
  const TMaskFrom extends string = TFrom,
  const TMaskTo extends string = "",
>(
  props: LinkTargetProps<TRouter, TFrom, TTo, TMaskFrom, TMaskTo> & NavigationMenuLinkOwnProps,
): React.ReactElement;

function NavigationMenuLink({
  active,
  closeOnClick,
  ...props
}:
  | NavigationMenuLinkProps
  | (AnyLinkTargetProps & NavigationMenuLinkOwnProps & { render?: never })) {
  const linkClassName =
    "flex items-center gap-related rounded-lg p-2 text-control transition-all outline-none hover:bg-muted focus:bg-muted focus-visible:outline-1 in-data-[slot=navigation-menu-content]:rounded-md [&:is([data-active],[aria-current=page])]:bg-muted-selected [&:is([data-active],[aria-current=page])]:hover:bg-muted [&:is([data-active],[aria-current=page])]:focus:bg-muted [&_svg:not([class*='size-'])]:size-4";

  // A destination renders `Link`, which takes the link options; the menu keeps its behaviour.
  if (hasLinkTarget(props)) {
    const { className, ...target } = props;

    return (
      <NavigationMenuPrimitive.Link
        data-slot="navigation-menu-link"
        active={active}
        closeOnClick={closeOnClick}
        className={cn(linkClassName, className)}
        render={linkFromTarget(target)}
      />
    );
  }

  const { className, ...rest } = props;

  return (
    <NavigationMenuPrimitive.Link
      data-slot="navigation-menu-link"
      active={active}
      closeOnClick={closeOnClick}
      className={cn(linkClassName, className)}
      {...rest}
    />
  );
}

const NavigationMenuIndicator = ({
  className,
  ...props
}: React.ComponentPropsWithRef<typeof NavigationMenuPrimitive.Icon>) => (
  <NavigationMenuPrimitive.Icon
    data-slot="navigation-menu-indicator"
    className={cn(
      "top-full z-1 flex h-1.5 items-end justify-center overflow-hidden data-[state=hidden]:animate-out data-[state=hidden]:fade-out data-[state=visible]:animate-in data-[state=visible]:fade-in",
      className,
    )}
    {...props}
  >
    <div className="relative top-[60%] h-2 w-2 rotate-45 rounded-ss-sm bg-border shadow-md" />
  </NavigationMenuPrimitive.Icon>
);

export {
  NavigationMenu,
  NavigationMenuContent,
  NavigationMenuIndicator,
  NavigationMenuItem,
  NavigationMenuLink,
  NavigationMenuList,
  NavigationMenuTrigger,
  navigationMenuTriggerStyle,
  NavigationMenuPositioner,
};
